#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: PaperExplorer, tower setup. Run on the Mac; it drives the tower over SSH.
# Run: scripts/setup-tower.sh   (override the SSH alias with TOWER=<alias>)
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "$0")/.."
TOTAL_STAGES=9
TOWER="${TOWER:-tower}"
SEED_ITEM_KEY="YAAC9XCX"
EMBED_MODEL="bge-m3"
EMBED_DIM=1024

# tw CMD runs CMD on the tower in a login shell (so ~/.local/bin etc. are on PATH).
tw()  { ssh "$TOWER" "bash -lc $(printf '%q' "$1")"; }
# twt CMD is tw with a terminal, for interactive or long-running commands.
twt() { ssh -t "$TOWER" "bash -lc $(printf '%q' "$1")"; }
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
# tower_env KEY VALUE upserts KEY=VALUE into the tower's .env; VALUE travels on stdin.
tower_env() {
  printf '%s' "$2" | tw "cd $REMOTE_DIR && v=\$(cat) && touch .env && { grep -v '^$1=' .env || true; } > .env.tmp && printf '%s=%s\n' '$1' \"\$v\" >> .env.tmp && mv .env.tmp .env && chmod 600 .env"
  printf '  %s✓ wrote%s %s → tower:%s/.env\n' "$GREEN" "$RESET" "$1" "$REMOTE_DIR"
}

banner "PaperExplorer · Tower setup (from the Mac)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Reach the tower"
branch=$(git branch --show-current)
say "Pushing your current branch ($branch) so the tower can check it out…"
git push -u origin "$branch"
if ssh -o ConnectTimeout=8 "$TOWER" true; then
  ok "ssh $TOWER works"
else
  warn "can't reach '$TOWER' over SSH; is it on and is the alias in ~/.ssh/config?"; exit 1
fi
TOWER_HOST=$(ssh -G "$TOWER" | awk '/^hostname /{print $2; exit}')
note "tower address on the network: $TOWER_HOST"
tw 'echo "  $(. /etc/os-release && echo "$PRETTY_NAME") · $(uname -m)"'
tw 'nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader 2>/dev/null | sed "s/^/  GPU: /"' \
  || warn "nvidia-smi not found; Ollama will run on CPU"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Tools on the tower"
missing=()
for tool in git gh uv docker ollama curl; do
  if tw "command -v $tool >/dev/null"; then ok "$tool"; else printf '  %s✗%s %s\n' "$RED" "$RESET" "$tool"; missing+=("$tool"); fi
done
if tw "docker compose version >/dev/null 2>&1"; then ok "docker compose"; else missing+=("docker-compose-plugin"); warn "docker compose plugin missing"; fi
if tw "docker info >/dev/null 2>&1"; then ok "docker runs without sudo"; else
  warn "docker isn't usable as your user (not running, or you're not in the 'docker' group)"
  note "  fix: sudo usermod -aG docker \$USER, then log out and back in on the tower"
  missing+=("docker access")
fi
if (( ${#missing[@]} )); then
  say ""
  step "On the tower (pop-os), install what's missing, e.g.:"
  note "  sudo apt install git gh curl docker.io docker-compose-plugin"
  note "  curl -LsSf https://astral.sh/uv/install.sh | sh"
  warn "re-run this wizard once they're installed"; exit 1
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub on the tower and clone the repo"
if tw "gh auth status >/dev/null 2>&1"; then ok "gh is signed in on the tower"; else
  say "gh isn't signed in on the tower; it will show a one-time code to enter at github.com/login/device."
  twt "gh auth login --hostname github.com --git-protocol https --web"
fi
tw "gh auth setup-git"
ok "git on the tower uses gh's token"
REMOTE_DIR="Projects/PaperExplorer"
ask REMOTE_DIR_IN "Where should the repo live on the tower? (relative to ~) [$REMOTE_DIR]:"
REMOTE_DIR="${REMOTE_DIR_IN:-$REMOTE_DIR}"
repo_url=$(git remote get-url origin)
if tw "test -d $REMOTE_DIR/.git"; then
  ok "repo already cloned at ~/$REMOTE_DIR"
  tw "cd $REMOTE_DIR && git fetch -q origin"
else
  tw "mkdir -p \$(dirname $REMOTE_DIR) && git clone -q $repo_url $REMOTE_DIR"
  ok "cloned into ~/$REMOTE_DIR"
fi
tw "cd $REMOTE_DIR && git switch -q $branch 2>/dev/null || git switch -q -c $branch --track origin/$branch"
ok "tower is on branch $branch"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Ollama: model, embeddings, network"
tw "curl -fsS localhost:11434/api/version" >/dev/null && ok "Ollama answers on the tower" \
  || { warn "Ollama isn't answering on localhost:11434 on the tower"; exit 1; }
if tw "ollama list | grep -q '^$EMBED_MODEL'"; then ok "$EMBED_MODEL already pulled"; else
  say "Pulling $EMBED_MODEL (about 1.2 GB)…"; twt "ollama pull $EMBED_MODEL"
fi
dim=$(tw "curl -fsS localhost:11434/v1/embeddings -H 'Content-Type: application/json' -d '{\"model\":\"$EMBED_MODEL\",\"input\":\"brain entropy\"}'" \
  | uv run --quiet python -c 'import json,sys; print(len(json.load(sys.stdin)["data"][0]["embedding"]))' || echo 0)
if [[ "$dim" == "$EMBED_DIM" ]]; then ok "OpenAI-compatible /v1/embeddings returns $dim dimensions"
else warn "embedding test returned '$dim' dimensions, expected $EMBED_DIM"; SKIPPED+=("check Ollama embeddings with $EMBED_MODEL"); fi
if curl -fsS --max-time 4 "http://$TOWER_HOST:11434/api/version" >/dev/null 2>&1; then
  ok "Ollama is reachable from the Mac and from containers"
else
  say "Ollama only listens on the tower's loopback. Containers and the Mac need it on the network."
  if tw "systemctl is-enabled ollama >/dev/null 2>&1" && confirm "Set OLLAMA_HOST=0.0.0.0:11434 (systemd override, needs sudo on the tower)?"; then
    twt "sudo mkdir -p /etc/systemd/system/ollama.service.d && printf '[Service]\nEnvironment=\"OLLAMA_HOST=0.0.0.0:11434\"\n' | sudo tee /etc/systemd/system/ollama.service.d/paperexplorer.conf >/dev/null && sudo systemctl daemon-reload && sudo systemctl restart ollama"
    sleep 3
    if curl -fsS --max-time 4 "http://$TOWER_HOST:11434/api/version" >/dev/null 2>&1; then ok "Ollama now reachable at http://$TOWER_HOST:11434"
    else warn "still not reachable from the Mac (firewall?)"; SKIPPED+=("make Ollama reachable on the LAN"); fi
  else
    SKIPPED+=("expose Ollama on the LAN: OLLAMA_HOST=0.0.0.0:11434 for the ollama service")
  fi
fi
note "No login protects Ollama; fine on a home network."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Zotero desktop on the tower and the Seed's PDF"
if tw "command -v zotero >/dev/null || test -x /opt/zotero/zotero || flatpak list 2>/dev/null | grep -qi zotero || ls ~/.local/share/applications 2>/dev/null | grep -qi zotero"; then
  ok "Zotero desktop is installed"
else
  warn "Zotero desktop not found on the tower"
  step "Install it on the tower (zotero.org/download, or: flatpak install flathub org.zotero.Zotero)."
  pause "Press Enter once installed."
fi
step "On the tower, open Zotero → Settings → Sync: sign in, and tick 'Sync attachment files in My Library'."
step "Let it sync once (green arrow in the toolbar)."
pause "Press Enter once Zotero has synced."
# Zotero may run as another desktop user (e.g. the admin), with storage shared read-only via ACL.
STORAGE_DIR=$(tw 'for d in "$HOME/Zotero/storage" /home/*/Zotero/storage; do [ -r "$d" ] && [ -x "$d" ] && { echo "$d"; break; }; done')
STORAGE_DIR="${STORAGE_DIR:-/home/ADMIN/Zotero/storage}"
ask STORAGE_IN "Zotero storage folder on the tower [$STORAGE_DIR]:"
STORAGE_DIR="${STORAGE_IN:-$STORAGE_DIR}"
tw "test -r '$STORAGE_DIR' && test -x '$STORAGE_DIR'" && ok "storage folder readable by $(tw whoami)" \
  || { warn "can't read $STORAGE_DIR as $(tw whoami); grant read access (setfacl -R -m u:<you>:rX …)"; exit 1; }
zid=$(_existing PE_ZOTERO_LIBRARY_ID || true); zkey=$(_existing PE_ZOTERO_API_KEY || true)
[[ -n "$zid" && -n "$zkey" ]] || { warn "Zotero values missing in the Mac's .env; run scripts/setup-mac.sh first"; exit 1; }
say "Looking up the Seed ($SEED_ITEM_KEY) and its PDF attachment…"
attachment=$(curl -fsS -H "Zotero-API-Key: $zkey" \
  "https://api.zotero.org/users/$zid/items/$SEED_ITEM_KEY/children?format=json" \
  | uv run --quiet python -c '
import json, sys
pdfs = [i["data"] for i in json.load(sys.stdin)
        if i["data"].get("itemType") == "attachment" and i["data"].get("contentType") == "application/pdf"]
print(pdfs[0]["key"] + "/" + pdfs[0].get("filename", "") if pdfs else "")
' || true)
if [[ -z "$attachment" ]]; then
  warn "the Seed has no PDF attachment in Zotero"; SKIPPED+=("attach the Seed's PDF in Zotero")
elif tw "test -f '$STORAGE_DIR/$attachment'"; then
  ok "Seed PDF is on the tower: $STORAGE_DIR/$attachment"
else
  warn "Seed PDF not in tower storage yet ($attachment); let Zotero finish syncing files"
  SKIPPED+=("Seed PDF not yet synced to the tower")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Configuration (.env) on the tower and the Mac"
tw "cd $REMOTE_DIR && test -f .env || cp .env.example .env"
pg_password=$(tw "cd $REMOTE_DIR && grep '^POSTGRES_PASSWORD=' .env | cut -d= -f2-" || true)
if [[ -z "$pg_password" || "$pg_password" == "change-me" ]]; then
  pg_password=$(openssl rand -hex 16); note "generated a new Postgres password"
fi
tower_env POSTGRES_USER paperexplorer
tower_env POSTGRES_DB paperexplorer
tower_env POSTGRES_PASSWORD "$pg_password"
tower_env PE_DATABASE_URL "postgresql://paperexplorer:$pg_password@localhost:5432/paperexplorer"
tower_env PE_EMBEDDING_BASE_URL "http://localhost:11434/v1"
tower_env PE_EMBEDDING_MODEL "$EMBED_MODEL"
tower_env PE_ZOTERO_LIBRARY_ID "$zid"
tower_env PE_ZOTERO_LIBRARY_TYPE user
tower_env PE_ZOTERO_API_KEY "$zkey"
tower_env PE_ZOTERO_STORAGE_DIR "$STORAGE_DIR"
tower_env ZOTERO_STORAGE_HOST_DIR "$STORAGE_DIR"
say ""
say "On the Mac: the database is reached through an SSH tunnel, embeddings over the LAN."
write_env PE_DATABASE_URL "postgresql://paperexplorer:$pg_password@localhost:5432/paperexplorer"
write_env PE_EMBEDDING_BASE_URL "http://$TOWER_HOST:11434/v1"
note "tunnel when needed: ssh -N -L 5432:localhost:5432 $TOWER"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Start the stack (db, api, web)"
say "Building images and starting containers on the tower (first build takes a few minutes)…"
twt "cd $REMOTE_DIR && docker compose up -d --build db api web"
sleep 5
tw "curl -fsS --retry 10 --retry-delay 2 --retry-all-errors localhost:8000/health" | sed 's/^/  api: /' \
  && ok "API healthy" || { warn "API not healthy: docker compose logs api"; SKIPPED+=("API health check"); }
if curl -fsS --max-time 5 "http://$TOWER_HOST:8080/" | grep -q "API connected"; then
  ok "web app reachable from the Mac at http://$TOWER_HOST:8080 and connected to the API"
  open_url "http://$TOWER_HOST:8080"
else
  warn "web app not reachable from the Mac at http://$TOWER_HOST:8080"; SKIPPED+=("web app check")
fi
tw "cd $REMOTE_DIR && docker compose run --rm pipeline version" | sed 's/^/  pipeline image: v/' || SKIPPED+=("pipeline image")
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Python environment and tests on the tower"
twt "cd $REMOTE_DIR && uv sync && uv run pre-commit install && uv run pytest -q -rs"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "VS Code Remote-SSH from the Mac"
if command -v code >/dev/null 2>&1; then
  code --install-extension ms-vscode-remote.remote-ssh >/dev/null && ok "Remote-SSH extension installed"
  if confirm "Open ~/$REMOTE_DIR on the tower in VS Code now?"; then
    code --remote "ssh-remote+$TOWER" "$(tw 'echo $HOME')/$REMOTE_DIR"
  fi
else
  warn "the 'code' command isn't on PATH"
  step "In VS Code: Cmd-Shift-P → 'Shell Command: Install code command in PATH', then re-run this stage."
  step "Or by hand: install 'Remote - SSH', then Cmd-Shift-P → 'Remote-SSH: Connect to Host…' → $TOWER."
  SKIPPED+=("VS Code Remote-SSH")
fi
pause

finish
